/* The Daily Five service worker. Generated by tools/build_site.py from tools/sw_template.js; edit the template, not sw.js. */
"use strict";
const BUILD = "e1013ce175b9";
const SHELL = "df-shell-" + BUILD;   // app shell: index.html, manifest, icons, data/index.json
const RT = "df-rt-" + BUILD;         // book text and scene files fetched while browsing
const FONTS = "df-fonts-1";          // Google Fonts css and font files
const OFF = "df-offline";            // books the reader chose to download (kept across versions)
const KEEP = [SHELL, RT, FONTS, OFF];
const PRECACHE = ["index.html", "manifest.webmanifest", "data/index.json", "icons/icon-192.png", "icons/icon-512.png", "icons/icon-maskable-512.png", "icons/apple-touch-icon.png", "icons/favicon-32.png", "icons/favicon.svg"];
const SCOPE = new URL(self.registration ? self.registration.scope : "./", self.location.href);
const abs = (p) => new URL(p, SCOPE).href;

self.addEventListener("install", (e) => {
  e.waitUntil(
    caches.open(SHELL)
      .then((c) => c.addAll(PRECACHE.map((p) => new Request(abs(p), { cache: "reload" }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("df-") && !KEEP.includes(k)).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin === self.location.origin) {
    if (!url.pathname.startsWith(SCOPE.pathname)) return;
    const rel = url.pathname.slice(SCOPE.pathname.length);
    if (req.mode === "navigate" || rel === "" || rel === "index.html") {
      e.respondWith(networkFirst(req, abs("index.html"), false));
    } else if (rel === "data/index.json") {
      e.respondWith(networkFirst(req, abs("data/index.json"), true));
    } else if (/\.(mp4|m4a|mp3|aac)$/i.test(rel)) {
      e.respondWith(media(req));
    } else if (rel.startsWith("scenes/") || rel.startsWith("data/books/")) {
      e.respondWith(cacheFirst(req, RT));
    } else if (PRECACHE.includes(rel)) {
      e.respondWith(cacheFirst(req, SHELL));
    }
    return;
  }
  if (url.hostname === "fonts.googleapis.com" || url.hostname === "fonts.gstatic.com") {
    e.respondWith(cacheFirst(req, FONTS));
  }
});

/* index.html and data/index.json: always try the network so new books show up; fall back to the copy on the device */
async function networkFirst(req, key, noStore) {
  const cache = await caches.open(SHELL);
  try {
    const res = await withTimeout(noStore ? fetch(req.url, { cache: "no-store" }) : fetch(req), 6000);
    if (res && res.ok) {
      cache.put(key, res.clone()).catch(() => {});
      return res;
    }
    const hit = await cache.match(key);
    return hit || res;
  } catch (err) {
    const hit = await cache.match(key);
    if (hit) return hit;
    throw err;
  }
}
function withTimeout(p, ms) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("timeout")), ms);
    p.then((r) => { clearTimeout(t); resolve(r); }, (e) => { clearTimeout(t); reject(e); });
  });
}

/* scenes and book text: their URLs carry a content version, so a cached copy is always current */
async function cacheFirst(req, name) {
  const hit = await caches.match(req.url);
  if (hit) return hit;
  const res = await fetch(req);
  if (res && (res.ok || res.type === "opaque")) {
    const c = await caches.open(name);
    c.put(req.url, res.clone()).catch(() => {});
  }
  return res;
}

/* audio: play from the device if the book was downloaded (with byte ranges, which iPhone Safari needs to play
   and seek); otherwise stream from the network and keep nothing, because the files are large */
async function media(req) {
  let hit = null;
  try { hit = await (await caches.open(OFF)).match(req.url); } catch (e) {}
  if (!hit) return fetch(req);
  return rangeResponse(req, hit);
}
async function rangeResponse(req, res) {
  const type = res.headers.get("content-type") || "audio/mp4";
  const blob = await res.blob();
  const size = blob.size;
  const range = req.headers.get("range");
  const base = { "Content-Type": type, "Accept-Ranges": "bytes" };
  if (!range) {
    return new Response(blob, { status: 200, headers: Object.assign({ "Content-Length": String(size) }, base) });
  }
  const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  let start, end;
  if (m && m[1] === "" && m[2] !== "") { start = Math.max(0, size - Number(m[2])); end = size - 1; }
  else if (m && m[1] !== "") { start = Number(m[1]); end = m[2] === "" ? size - 1 : Math.min(Number(m[2]), size - 1); }
  if (!m || start === undefined || start >= size || start > end) {
    return new Response(null, { status: 416, headers: Object.assign({ "Content-Range": "bytes */" + size }, base) });
  }
  return new Response(blob.slice(start, end + 1, type), {
    status: 206,
    statusText: "Partial Content",
    headers: Object.assign({ "Content-Range": "bytes " + start + "-" + end + "/" + size, "Content-Length": String(end - start + 1) }, base),
  });
}
